package raft

import (
	"os"
	"path"
	"testing"
)

// Snapshot names carry the term and index they cover, and comparing them as text
// puts "1_10.ss" before "1_9.ss". A server that loaded the wrong one would come
// back at an index it had already moved past.
func TestLatestSnapshotName(t *testing.T) {
	tests := []struct {
		name      string
		filenames []string
		want      string
	}{
		{"none", nil, ""},
		{"single", []string{"1_5.ss"}, "1_5.ss"},
		{"index past a digit", []string{"1_9.ss", "1_10.ss"}, "1_10.ss"},
		{"index over term", []string{"9_1.ss", "1_10.ss"}, "1_10.ss"},
		{"same index, later term", []string{"1_10.ss", "2_10.ss"}, "2_10.ss"},
		{"ignores other files", []string{"1_5.ss.tmp", "notes.txt", "1_5.ss"}, "1_5.ss"},
		{"only other files", []string{"1_5.ss.tmp", "notes.txt"}, ""},
		// A snapshot is staged next to its own path before it is put in place, so
		// one left behind can cover more of the log than the one that counts.
		{"ignores a staged snapshot ahead of it", []string{"1_5.ss", "1_10.ss.tmp"}, "1_5.ss"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if got := latestSnapshotName(test.filenames); got != test.want {
				t.Errorf("latestSnapshotName(%v) = %q, want %q", test.filenames, got, test.want)
			}
		})
	}
}

// The same thing through LoadSnapshot, with both snapshots really on disk.
func TestLoadSnapshotPicksTheHighestIndex(t *testing.T) {
	s := newTestServer("1", &testTransporter{})
	srv := s.(*server)
	srv.stateMachine = &testStateMachine{
		saveFunc:     func() ([]byte, error) { return nil, nil },
		recoveryFunc: func([]byte) error { return nil },
	}
	if err := os.MkdirAll(path.Join(s.Path(), "snapshot"), 0700); err != nil {
		t.Fatalf("create snapshot dir: %v", err)
	}

	for _, snapshot := range []*Snapshot{
		{9, 1, nil, []byte("older"), s.SnapshotPath(9, 1)},
		{10, 1, nil, []byte("newer"), s.SnapshotPath(10, 1)},
	} {
		if err := snapshot.save(); err != nil {
			t.Fatalf("save snapshot: %v", err)
		}
	}

	if err := s.LoadSnapshot(); err != nil {
		t.Fatalf("load snapshot: %v", err)
	}
	if srv.snapshot.LastIndex != 10 {
		t.Errorf("loaded the snapshot at index %d, want 10", srv.snapshot.LastIndex)
	}
	if string(srv.snapshot.State) != "newer" {
		t.Errorf("loaded state %q, want %q", srv.snapshot.State, "newer")
	}
}

package raft

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

// Ensure that we can listen and dispatch events.
func TestDispatchEvent(t *testing.T) {
	var count int
	dispatcher := newEventDispatcher(nil)
	dispatcher.AddEventListener("foo", func(e Event) {
		count += 1
	})
	dispatcher.AddEventListener("foo", func(e Event) {
		count += 10
	})
	dispatcher.AddEventListener("bar", func(e Event) {
		count += 100
	})
	dispatcher.DispatchEvent(&event{typ: "foo", value: nil, prevValue: nil})
	assert.Equal(t, 11, count)
}

// Ensure that we can add and remove a listener.
func TestRemoveEventListener(t *testing.T) {
	var count int
	f0 := func(e Event) {
		count += 1
	}
	f1 := func(e Event) {
		count += 10
	}

	dispatcher := newEventDispatcher(nil)
	dispatcher.AddEventListener("foo", f0)
	dispatcher.AddEventListener("foo", f1)
	dispatcher.DispatchEvent(&event{typ: "foo"})
	dispatcher.RemoveEventListener("foo", f0)
	dispatcher.DispatchEvent(&event{typ: "foo"})
	assert.Equal(t, 21, count)
}

// Ensure that event is properly passed to listener.
func TestEventListener(t *testing.T) {
	dispatcher := newEventDispatcher("X")
	dispatcher.AddEventListener("foo", func(e Event) {
		assert.Equal(t, "foo", e.Type())
		assert.Equal(t, "X", e.Source())
		assert.Equal(t, 10, e.Value())
		assert.Equal(t, 20, e.PrevValue())
	})
	dispatcher.DispatchEvent(&event{typ: "foo", value: 10, prevValue: 20})
}

// Benchmark the performance of event dispatch.
func BenchmarkEventDispatch(b *testing.B) {
	dispatcher := newEventDispatcher(nil)
	dispatcher.AddEventListener("xxx", func(e Event) {})
	for i := 0; i < b.N; i++ {
		dispatcher.DispatchEvent(&event{typ: "foo", value: 10, prevValue: 20})
	}
}

package raft

import (
	"fmt"
	"sync"
	"testing"
	"time"
)

// The peer map is read outside the event loop — Peers hands out a copy,
// FlushCommitIndex writes the configuration, TakeSnapshot records the membership
// in a snapshot — while AddPeer and RemovePeer write it. Every one of those has
// to hold the same lock: a reader that takes it alone is still racing a writer
// that does not, and a concurrent map iteration and map write is answered by the
// runtime killing the process.
//
// The server is left stopped so that this reports on the peer map alone, rather
// than on the log and snapshot fields its loops would be touching at the same
// time.
func TestPeerMapReadWhileMembershipChanges(t *testing.T) {
	s := newTestServer("1", &testTransporter{})

	stop := make(chan struct{})
	var wg sync.WaitGroup

	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; ; i++ {
			select {
			case <-stop:
				return
			default:
			}
			name := fmt.Sprintf("peer-%d", i%4)
			if err := s.AddPeer(name, ""); err != nil {
				t.Errorf("AddPeer: %v", err)
				return
			}
			if err := s.RemovePeer(name); err != nil {
				t.Errorf("RemovePeer: %v", err)
				return
			}
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
			}
			s.Peers()
			s.MemberCount()
		}
	}()

	time.Sleep(500 * time.Millisecond)
	close(stop)
	wg.Wait()
}

