//--------------------------------------
// Recovery
//--------------------------------------

// Waits for a server to have committed up to an index. How long replication or
// an election takes is not a fixed quantity, so a test that expects one to have
// happened waits for it rather than for an interval that looks long enough.
//
// The wait is for at least the index, not exactly it: a further election adds
// another no-op, so pinning the number pins how many elections the run had, and
// what these tests are checking is that everyone caught up.
func waitForCommitIndex(t *testing.T, name string, s Server, want uint64) {
	t.Helper()

	deadline := time.Now().Add(5 * time.Second)
	for s.CommitIndex() < want {
		if time.Now().After(deadline) {
			t.Fatalf("%s commitIndex is invalid [%d/%d]", name, s.CommitIndex(), want)
		}
		time.Sleep(time.Millisecond)
	}
}

// Ensure that a follower cannot execute a command.
func TestServerRecoverFromPreviousLogAndConf(t *testing.T) {
	// Initialize the servers.
	var mutex sync.RWMutex
	servers := map[string]Server{}

	transporter := &testTransporter{}
	transporter.sendVoteRequestFunc = func(s Server, peer *Peer, req *RequestVoteRequest) *RequestVoteResponse {
		mutex.RLock()
		target := servers[peer.Name]
		mutex.RUnlock()

		b, _ := json.Marshal(req)
		clonedReq := &RequestVoteRequest{}
		json.Unmarshal(b, clonedReq)

		return target.RequestVote(clonedReq)
	}
	transporter.sendAppendEntriesRequestFunc = func(s Server, peer *Peer, req *AppendEntriesRequest) *AppendEntriesResponse {
		mutex.RLock()
		target := servers[peer.Name]
		mutex.RUnlock()

		b, _ := json.Marshal(req)
		clonedReq := &AppendEntriesRequest{}
		json.Unmarshal(b, clonedReq)

		return target.AppendEntries(clonedReq)
	}

	disTransporter := &testTransporter{}
	disTransporter.sendVoteRequestFunc = func(s Server, peer *Peer, req *RequestVoteRequest) *RequestVoteResponse {
		return nil
	}
	disTransporter.sendAppendEntriesRequestFunc = func(s Server, peer *Peer, req *AppendEntriesRequest) *AppendEntriesResponse {
		return nil
	}

	var names []string
	var paths = make(map[string]string)

	n := 5

	// add n servers
	for i := 1; i <= n; i++ {
		names = append(names, strconv.Itoa(i))
	}

	var leader Server
	for _, name := range names {
		s := newTestServer(name, transporter)

		mutex.Lock()
		servers[name] = s
		mutex.Unlock()
		paths[name] = s.Path()

		if name == "1" {
			leader = s
			s.SetHeartbeatInterval(testHeartbeatInterval)
			s.Start()
			time.Sleep(testHeartbeatInterval)
		} else {
			s.SetElectionTimeout(testElectionTimeout)
			s.SetHeartbeatInterval(testHeartbeatInterval)
			s.Start()
			time.Sleep(testHeartbeatInterval)
		}
		if _, err := leader.Do(&DefaultJoinCommand{Name: name}); err != nil {
			t.Fatalf("Unable to join server[%s]: %v", name, err)
		}

	}

	// commit some commands
	for i := 0; i < 10; i++ {
		if _, err := leader.Do(&testCommand2{X: 1}); err != nil {
			t.Fatalf("cannot commit command: %s", err.Error())
		}
	}

	// Everyone has to catch up before any of them is stopped: stopping the leader
	// first would leave the rest with nothing to catch up from.
	for _, name := range names {
		waitForCommitIndex(t, name, servers[name], 16)
	}
	for _, name := range names {
		servers[name].Stop()
	}

	for _, name := range names {
		// with old path and disable transportation
		s := newTestServerWithPath(name, disTransporter, paths[name])
		servers[name] = s

		s.Start()

		// should only commit to the last join command
		if s.CommitIndex() != 6 {
			t.Fatalf("%s recover phase 1 commitIndex is invalid [%d/%d]", name, s.CommitIndex(), 6)
		}

		// peer conf should be recovered
		if len(s.Peers()) != 4 {
			t.Fatalf("%s recover phase 1 peer failed! [%d/%d]", name, len(s.Peers()), 4)
		}
	}

	// let nodes talk to each other
	for _, name := range names {
		servers[name].SetTransporter(transporter)
	}

	// should commit to the previous index + 1(nop command when new leader elected)
	for _, name := range names {
		waitForCommitIndex(t, name, servers[name], 17)
	}
	for _, name := range names {
		servers[name].Stop()
	}
}

// Ensure that a server's currentTerm and votedFor survive a restart,
// preventing a double-vote in the same term that could cause split-brain.
func TestServerVoteStatePersistsAcrossRestart(t *testing.T) {
	s := newTestServer("1", &testTransporter{})
	serverPath := s.Path()

	s.Start()
	if _, err := s.Do(&DefaultJoinCommand{Name: s.Name()}); err != nil {
		t.Fatalf("Server %s unable to join: %v", s.Name(), err)
	}

	// Vote for candidate "A" at term 5.
	resp := s.RequestVote(newRequestVoteRequest(5, "A", 3, 5))
	if !resp.VoteGranted {
		t.Fatalf("Vote should have been granted to A")
	}
	if s.Term() != 5 {
		t.Fatalf("Term should be 5, got %v", s.Term())
	}
	if s.VotedFor() != "A" {
		t.Fatalf("VotedFor should be A, got %v", s.VotedFor())
	}

	// Simulate crash/restart: stop the server and create a new one
	// at the same path (preserving on-disk state).
	s.Stop()

	s2 := newTestServerWithPath("1", &testTransporter{}, serverPath)
	s2.Start()
	defer s2.Stop()

	// Verify term and votedFor survived the restart.
	if s2.Term() != 5 {
		t.Fatalf("After restart, term should be 5, got %v", s2.Term())
	}
	if s2.VotedFor() != "A" {
		t.Fatalf("After restart, votedFor should be A, got %v", s2.VotedFor())
	}

	// A second candidate "B" requests a vote at the same term 5.
	// This MUST be denied — granting it would allow two leaders in term 5.
	resp = s2.RequestVote(newRequestVoteRequest(5, "B", 3, 5))
	if resp.VoteGranted {
		t.Fatalf("Vote for B at term 5 should have been denied (already voted for A)")
	}

	// Voting for the SAME candidate "A" again at term 5 should still succeed.
	resp = s2.RequestVote(newRequestVoteRequest(5, "A", 3, 5))
	if !resp.VoteGranted {
		t.Fatalf("Re-vote for A at term 5 should have been granted")
	}

	// A vote at a HIGHER term should be granted (new term, new election).
	resp = s2.RequestVote(newRequestVoteRequest(6, "B", 3, 5))
	if !resp.VoteGranted {
		t.Fatalf("Vote for B at term 6 should have been granted")
	}
	if s2.VotedFor() != "B" {
		t.Fatalf("VotedFor should be B after term 6 vote, got %v", s2.VotedFor())
	}
}

// Ensure that currentTerm incremented during candidateLoop (without any log
